/** Kanban board on a project room's wall: post-its in a few states, varied by the room's seed. */
export function kanban(x, y, seed) {
  const colors = ['#f5c97a', '#8ab4ff', '#ff9a4d', '#c8f560', '#c8f560', '#f5c97a', '#8ab4ff', '#c8f560']
  let notes = ''
  for (let col = 0; col < 3; col++) {
    for (let row = 0; row < 2; row++) {
      for (let k = 0; k < 2; k++) {
        const bit = (seed >>> (col * 4 + row * 2 + k)) & 1
        if (!bit && !(col === 2 && row === 0)) continue
        const c = colors[(seed >>> (col * 3 + row + k)) % colors.length]
        notes += `<rect x="${x + 3 + col * 21 + k * 8}" y="${y + 3 + row * 7}" width="6" height="5" fill="${c}"/>`
      }
    }
  }
  return (
    `<rect x="${x}" y="${y}" width="64" height="21" rx="2" fill="#c3c8cf"/>` +
    `<path d="M${x + 21.5} ${y + 2.5}V${y + 18.5}M${x + 42.5} ${y + 2.5}V${y + 18.5}" stroke="#98a0aa" stroke-width="0.8"/>${notes}`
  )
}
